// penyimpanan mengganti isi catatan; riwayat siapa-kapan ada di order_events
// yang ditulis repository pada transaksi yang sama.
func (q *Queries) UpdateOrderNoteAdmin(ctx context.Context, arg UpdateOrderNoteAdminParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateOrderNoteAdmin, arg.NoteAdmin, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
